import math

def _t():
    for a in range(-50, 50):
        for m in range(-50, 50):
            if m != 0 and math.gcd(a, m) == 1:
                inv = pow(a, -1, m)
                assert inv == inv % m, ('assertEqual', inv, inv % m)
                assert (inv * a - 1) % m == 0, ('assertEqual', (inv * a - 1) % m, 0)
                assert pow(a, -2, m) == pow(inv, 2, m), ('assertEqual', pow(a, -2, m), pow(inv, 2, m))
                assert pow(a, -3, m) == pow(inv, 3, m), ('assertEqual', pow(a, -3, m), pow(inv, 3, m))
                assert pow(a, -1001, m) == pow(inv, 1001, m), ('assertEqual', pow(a, -1001, m), pow(inv, 1001, m))
            else:
                try:
                    pow(a, -1, m)
                except ValueError as _exc:
                    pass
                else:
                    raise AssertionError('assertRaises: did not raise')
                try:
                    pow(a, -2, m)
                except ValueError as _exc:
                    pass
                else:
                    raise AssertionError('assertRaises: did not raise')
                try:
                    pow(a, -1001, m)
                except ValueError as _exc:
